 912	/// Move the cursor to some absolute position.
 913	pub fn cursorAbsolute(self: *Screen, x: size.CellCountInt, y: size.CellCountInt) void {
 914	    assert(x < self.pages.cols);
 915	    assert(y < self.pages.rows);
 916	    defer self.assertIntegrity();
 917	
 918	    var page_pin = if (y < self.cursor.y)
 919	        self.cursor.page_pin.up(self.cursor.y - y).?
 920	    else if (y > self.cursor.y)
 921	        self.cursor.page_pin.down(y - self.cursor.y).?
 922	    else
 923	        self.cursor.page_pin.*;
 924	    page_pin.x = x;
 925	    self.cursor.x = x; // Must be set before cursorChangePin
 926	    self.cursor.y = y;
 927	    self.cursorChangePin(page_pin);
 928	    const page_rac = self.cursor.page_pin.rowAndCell();
 929	    self.cursor.page_row = page_rac.row;
 930	    self.cursor.page_cell = page_rac.cell;
 931	}
